    def forward(self, logits: torch.Tensor) -> torch.Tensor:
        if self.training:
            sigmoid_out = torch.sigmoid(logits)
            hard = (sigmoid_out > 0.5).to(logits.dtype)
            return hard - sigmoid_out.detach() + sigmoid_out
        else:
            return (logits > 0).to(logits.dtype)



